CREATE TABLE "usuarios" (
  "id_usuario" integer PRIMARY KEY,
  "username" varchar NOT NULL,
  "password" varchar NOT NULL,
  "email" varchar NOT NULL,
  "administrador" boolean DEFAULT false
);
CREATE TABLE "subunidades" (
  "id_subunidade" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "subunidade" varchar NOT NULL
);

CREATE TABLE "tipos_transacoes" (
  "id_tipo_transacao" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo_transacao" varchar NOT NULL
);

-- CUSTEIO OU CAPITAL
CREATE TABLE "tipo_despesa" (
  "id_tipo_despesa" integer PRIMARY KEY,
  "tipo_despesa" varchar
);
-- BOLSA 2A, BOLSA FIM
CREATE TABLE "finalidades" (
  "id_finalidade" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_tabela_finalidade" integer DEFAULT null,
  "id_tipo_despesa" integer,
  "finalidade" varchar NOT NULL
);
-- BOLSA, HOSPEDAGEM
CREATE TABLE "tabelas_finalidades" (
  "id_tabela_finalidade" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tabela_finalidade" varchar NOT NULL
);

-- PEN PGP, DOCUMENTO, 
CREATE TABLE "tipos_documento" (
  "id_tipo_documento" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo_documento" varchar NOT NULL
);

-- CANCELADO, A CAMINHO...
CREATE TABLE "status" (
  "id_status" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "status" varchar NOT NULL
);

CREATE TABLE "transacoes" (
  "id_transacao" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_tipo_transacao" integer NOT NULL,
  "id_transacao_pai" integer DEFAULT null,
  "id_finalidade" integer DEFAULT null,
  "id_subunidade_credora" integer DEFAULT null,
  "id_subunidade_executora" integer DEFAULT null,
  "id_usuario" integer NOT NULL,
  "id_status" integer NOT NULL,
  "id_tipo_documento" integer DEFAULT null,
  "descricao" varchar DEFAULT null,
  "montante" decimal(15,2) DEFAULT 0,
  "documento" varchar DEFAULT null,
  "data_referencia" date DEFAULT (now()),
  "data_lancamento" timestamp DEFAULT (now()),
  "data_atualizacao" timestamp DEFAULT (now())
);

CREATE TABLE "beneficiarios" (
  "id_beneficiario" integer PRIMARY KEY,
  "nome_beneficiario" varchar,
  "matricula" varchar DEFAULT null
);

CREATE TABLE "bolsas" (
  "id_transacao" integer PRIMARY KEY,
  "id_beneficiario" integer,
  "op_sf" varchar NOT NULL
);

CREATE TABLE "hospedagem" (
  "id_transacao" integer PRIMARY KEY,
  "id_beneficiario" integer,
  "quantidade_diarias" float
);

CREATE TABLE "diarias" (
  "id_transacao" integer PRIMARY KEY,
  "id_beneficiario" integer,
  "local" varchar,
  "quantidade_diarias" float
);

CREATE TABLE "passagens" (
  "id_transacao" integer PRIMARY KEY,
  "id_beneficiario" integer,
  "trecho" varchar
);

CREATE TABLE "refeicoes" (
  "id_transacao" integer PRIMARY KEY,
  "id_beneficiario" integer,
  "quantidade" integer
);

CREATE TABLE "manutencao" (
  "id_transacao" integer PRIMARY KEY,
  "setor" varchar
);

CREATE TABLE "grafica" (
  "id_transacao" integer PRIMARY KEY,
  "cnpj_empresa" varchar
);

CREATE TABLE "empenho" (
  "id_transacao" integer PRIMARY KEY,
  "empenho_sie" varchar,
  "empenho_siafe" varchar DEFAULT null
);

